#!/usr/bin/env node
// Which generated files are committed, and by what rule.
//
// A generated module is committed when its generator needs a toolchain or a
// network that CI, or a fresh clone, does not have. That is the whole rule, and
// it is what keeps a fresh clone building with Node, Rust with cargo-ndk, a JDK
// and the npm, crates.io and Maven registries, and nothing else. About forty thousand lines of this tree are machine output under it: the
// UniFFI bindings, the C++ bridge, the map renderer and its glyph and sprite
// blobs, and the muscle polygons.
//
// It used to be a block of commented-out paths in `.gitignore` saying "tracked
// for CI simplification (see build system plan)", pointing at a plan no longer
// in the tree, so the next generated file would have been argued from scratch.
//
// What is NOT covered: output a build makes on the machine that builds, which
// is platform-specific and belongs to nobody's clone. Those are ignored
// deliberately and listed in IGNORED_BY_RULE below. Git LFS stays ruled out:
// this repository has no remote to serve it.
//
// The check is the index rather than a hand-listed set of files: a generated
// file that is untracked, or newly added to `.gitignore`, fails and names
// itself.

import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { join } from 'node:path';

import { gitFreeEnv } from './lib/indexedSources.mjs';

// Paths whose generated output a build makes locally, with the reason. These
// are prefixes, and each one is output no clone should carry.
const IGNORED_BY_RULE = [
  // Per-platform UniFFI output, regenerated by npm run ffi:generate on
  // the machine that builds.
  'modules/veloqrs/android/src/main/java/uniffi/',
  'modules/veloqrs/ios/Generated/',
  'modules/veloqrs/ios/cpp/',
  // The basemap sprite and glyphs, copied from modules/veloqrs/assets/basemap
  // by the podspec when CocoaPods reads it.
  'modules/veloqrs/ios/BasemapAssets/',
  // Compiled libraries, built from source by the stated toolchain.
  'modules/veloqrs/android/src/main/jniLibs/',
  'modules/veloqrs/build/',
  'modules/veloqrs/ios/Frameworks/',
  // Expo's prebuild output. The tracked parts are named in .gitignore.
  'android/',
  'ios/',
];

// What a generated file looks like here: the `.generated.` convention, plus the
// two directories whose whole contents are bindgen output.
const GENERATED_DIRS = ['modules/veloqrs/src/generated/', 'modules/veloqrs/cpp/generated/'];

function isGenerated(path) {
  return path.includes('.generated.') || GENERATED_DIRS.some((dir) => path.startsWith(dir));
}

function coveredByBuildRule(path) {
  return IGNORED_BY_RULE.some((prefix) => path.startsWith(prefix));
}

// Where a generated file may live. The listing is pathspec-limited to these,
// because `--ignored` over the whole tree enumerates `node_modules` as well and
// that is hundreds of thousands of paths: the first run of this guard in the
// main checkout died on `spawnSync git ENOBUFS`, where a worktree with a
// symlinked `node_modules` had passed.
const SEARCHED = ['src', 'modules/veloqrs/src', 'modules/veloqrs/cpp', 'scripts', 'config'];

function git(root, args) {
  return execFileSync('git', args, {
    cwd: root,
    // `cwd` does not decide which index git reads. The pre-commit hook exports
    // GIT_DIR and GIT_INDEX_FILE and those win, so the guard would answer about
    // the repository the hook is committing rather than the root it was given,
    // and read that index against this disk.
    env: gitFreeEnv(),
    encoding: 'utf8',
    // A generated blob is megabytes and the listings are long. The default
    // 1 MB is what failed, so this is room rather than a limit anyone meets.
    maxBuffer: 64 * 1024 * 1024,
  });
}

function main() {
  const rootFlag = process.argv.indexOf('--root');
  const root = rootFlag === -1 ? process.cwd() : process.argv[rootFlag + 1];

  const tracked = new Set(git(root, ['ls-files']).split('\n').filter(Boolean));

  // Untracked first: a generated file nobody added is as uncommitted as an
  // ignored one, and `--others` reports both once `--ignored` is asked for.
  const searched = SEARCHED.filter((dir) => existsSync(join(root, dir)));
  const others = git(root, ['ls-files', '--others', '--exclude-standard', '--', ...searched])
    .split('\n')
    .filter(Boolean);
  const ignored = git(root, [
    'ls-files',
    '--others',
    '--ignored',
    '--exclude-standard',
    '--',
    ...searched,
  ])
    .split('\n')
    .filter(Boolean);

  const offenders = [...others, ...ignored]
    .filter((path) => isGenerated(path))
    .filter((path) => !coveredByBuildRule(path))
    .filter((path) => !tracked.has(path))
    .sort();

  if (offenders.length > 0) {
    console.error('A generated file is not committed. The rule is:');
    console.error('');
    console.error('  A generated module is committed when its generator needs a toolchain or a');
    console.error('  network that CI, or a fresh clone, does not have.');
    console.error('');
    console.error('So `git clone && npm run android` works with no network beyond npm.');
    console.error('');
    for (const path of offenders) console.error(`  ${path}`);
    console.error('');
    console.error('Commit it, or, if it is output a build makes on the machine that builds,');
    console.error('add its directory to IGNORED_BY_RULE in this script with the reason.');
    process.exit(1);
  }

  console.log(`Generated-file guard: ${[...tracked].filter(isGenerated).length} committed.`);
}

main();
